        findPromptArea() {
            const selectors = [
                '#prompt-textarea[contenteditable="true"]',
                'div[contenteditable="true"][id="prompt-textarea"]',
                'div[data-testid="prompt-textarea"][contenteditable="true"]',
                'textarea#prompt-textarea',
                'textarea[data-testid="prompt-textarea"]'
            ];

            for (const selector of selectors) {
                const element = document.querySelector(selector);
                if (element) return element;
            }
            return null;
        },

        getSendButtonSelectors() {
            return [
                'button[aria-label="Send prompt"]',
                'button[data-testid="send-button"]',
                'button.btn.relative.btn-primary:not([aria-label="Dictate button"])'
            ];
        },

        findSendButton() {
            const selectors = this.getSendButtonSelectors();
            for (const selector of selectors) {
                const button = document.querySelector(selector);
                if (button && !button.disabled) return button;
            }
            return null;
        },

        isSendButtonElement(element) {
            if (!element || !element.matches) return false;
            return this.getSendButtonSelectors().some((selector) => {
                try {
                    return element.matches(selector);
                } catch (_error) {
                    return false;
                }
            });
        },

        isEditableElement(element) {
            if (!element || !element.tagName) return false;
            if (element.tagName === 'INPUT' || element.tagName === 'TEXTAREA') return true;
            return element.isContentEditable === true || element.getAttribute('contenteditable') === 'true';
        },

        isPromptFocused(promptArea) {
            if (!promptArea) return false;
            const activeElement = document.activeElement;
            if (!activeElement) return false;
            return activeElement === promptArea || promptArea.contains(activeElement);
        },

        setPromptText(text) {
            const promptArea = this.findPromptArea();
            if (!promptArea) return false;
            const normalizedText = String(text || '').replace(/\r\n/g, '\n');

            promptArea.focus();
            if (promptArea.tagName === 'TEXTAREA' || promptArea.tagName === 'INPUT') {
                promptArea.value = normalizedText;
                promptArea.dispatchEvent(new Event('input', { bubbles: true }));
                promptArea.selectionStart = promptArea.value.length;
                promptArea.selectionEnd = promptArea.value.length;
                return true;
            }

            const selection = window.getSelection();
            let insertedWithCommand = false;
            if (selection) {
                const selectAllRange = document.createRange();
                selectAllRange.selectNodeContents(promptArea);
                selection.removeAllRanges();
                selection.addRange(selectAllRange);
            }

            try {
                if (typeof document.execCommand === 'function') {
                    insertedWithCommand = document.execCommand('insertText', false, normalizedText);
                }
            } catch (_error) {
                insertedWithCommand = false;
            }

            if (!insertedWithCommand) {
                promptArea.textContent = normalizedText;
            }

            promptArea.dispatchEvent(new Event('input', { bubbles: true }));
            if (selection) {
                const range = document.createRange();
                range.selectNodeContents(promptArea);
                range.collapse(false);
                selection.removeAllRanges();
                selection.addRange(range);
            }
            return true;
        },

        getPromptText(promptArea = null) {
            const el = promptArea || this.findPromptArea();
            if (!el) return '';
            if (el.tagName === 'TEXTAREA' || el.tagName === 'INPUT') {
                return String(el.value || '').replace(/\r\n/g, '\n');
            }
            return String(el.innerText || el.textContent || '').replace(/\r\n/g, '\n');
        },

        capturePromptForHistoryFromPromptArea(source = '') {
            if (!this.isChatGPTPage || !this.CONFIG.PROMPT_HISTORY_NAV_ENABLED) return;
            const promptArea = this.findPromptArea();
            if (!promptArea) return;
            const text = this.getPromptText(promptArea);
            if (!text || !text.trim()) return;
            this.addPromptToHistory(text);
            if (this.CONFIG.SHOW_DIAGNOSTICS_PANEL) {
                console.debug('[TTS] Prompt captured for history', {
                    source,
                    length: text.length
                });
            }
        },

        capturePromptForNativeEnterSend(event) {
            if (!this.isChatGPTPage || !this.CONFIG.PROMPT_HISTORY_NAV_ENABLED) return;
            if (this.CONFIG.ENTER_TO_SEND_ENABLED) return;
            if (!event || event.key !== 'Enter') return;
            if (event.shiftKey || event.ctrlKey || event.altKey || event.metaKey) return;

            const promptArea = this.findPromptArea();
            if (!promptArea || !this.isPromptFocused(promptArea)) return;
            this.capturePromptForHistoryFromPromptArea('native-enter');
        },

        handleSendButtonCapture(event) {
            if (!this.isChatGPTPage || !this.CONFIG.PROMPT_HISTORY_NAV_ENABLED) return;
            const target = event && event.target && event.target.closest ? event.target.closest('button') : null;
            if (!target || !this.isSendButtonElement(target)) return;
            this.capturePromptForHistoryFromPromptArea('send-button-click');
        },

        normalizePromptHistoryText(text) {
            return String(text || '').replace(/\r\n/g, '\n').trim();
        },

        addPromptToHistory(text) {
            const normalized = this.normalizePromptHistoryText(text);
            if (!normalized) return;
            const maxChars = Math.max(500, Number(this.CONFIG.PROMPT_HISTORY_MAX_CHARS) || 6000);
            if (normalized.length > maxChars) return;
            const last = this.promptHistory.length > 0 ? this.promptHistory[this.promptHistory.length - 1] : '';
            if (last === normalized) return;

            this.promptHistory.push(normalized);
            const maxItems = Math.max(20, Number(this.CONFIG.PROMPT_HISTORY_MAX) || 200);
            if (this.promptHistory.length > maxItems) {
                this.promptHistory.splice(0, this.promptHistory.length - maxItems);
            }
            this.promptHistoryCursor = -1;
            this.promptHistoryDraft = '';
            this.promptHistoryDraftTooLarge = false;
        },

        extractCleanText(element) {
            if (!element) return '';
            const clone = element.cloneNode(true);
            clone.querySelectorAll('[data-tmx-control], .tmx-copy-row, .tmx-copy-button, [data-tts-ui]').forEach((node) => node.remove());
            return this.normalizePromptHistoryText(clone.innerText || clone.textContent || '');
        },

        extractUserMessageText(messageElement) {
            if (!messageElement || messageElement.getAttribute('data-message-author-role') !== 'user') return '';
            const preferredNode = messageElement.querySelector('.whitespace-pre-wrap');
            if (preferredNode) {
                return this.extractCleanText(preferredNode);
            }
            return this.extractCleanText(messageElement);
        },

        hydratePromptHistoryFromDom() {
            this.promptHistory = [];
            const userMessages = Array.from(document.querySelectorAll('[data-message-author-role="user"]'));
            userMessages.forEach((messageElement) => {
                const text = this.extractUserMessageText(messageElement);
                if (text) this.addPromptToHistory(text);
            });
            this.promptHistoryCursor = -1;
            this.promptHistoryDraft = '';
            this.promptHistoryDraftTooLarge = false;
        },

        initPromptHistoryObserver() {
            if (!this.isChatGPTPage || this.promptHistoryObserver) return;
            this.hydratePromptHistoryFromDom();
            this.promptHistoryObserver = new MutationObserver((mutations) => {
                for (const mutation of mutations) {
                    if (!mutation.addedNodes || mutation.addedNodes.length === 0) continue;
                    for (const node of mutation.addedNodes) {
                        if (node.nodeType !== Node.ELEMENT_NODE) continue;
                        const element = node;
                        const candidates = [];
                        if (element.matches && element.matches('[data-message-author-role="user"]')) {
                            candidates.push(element);
                        }
                        if (element.querySelectorAll) {
                            candidates.push(...element.querySelectorAll('[data-message-author-role="user"]'));
                        }
                        candidates.forEach((candidate) => {
                            const text = this.extractUserMessageText(candidate);
                            if (text) this.addPromptToHistory(text);
                        });
                    }
                }
            });
            this.promptHistoryObserver.observe(document.body, { childList: true, subtree: true });
        },

        setPromptHistoryNavigationEnabled(enabled, silent = false) {
            const nextValue = Boolean(enabled);
            if (this.CONFIG.PROMPT_HISTORY_NAV_ENABLED === nextValue) return;
            this.CONFIG.PROMPT_HISTORY_NAV_ENABLED = nextValue;
            this.promptHistoryCursor = -1;
            this.promptHistoryDraft = '';
            this.promptHistoryDraftTooLarge = false;
            if (!silent) {
                this.showNotification(`Prompt history nav ${nextValue ? 'on' : 'off'}`);
            }
        },

        handlePromptHistoryHotkeys(event) {
            if (!this.isChatGPTPage || !this.CONFIG.PROMPT_HISTORY_NAV_ENABLED) return false;
            if (!event.ctrlKey || event.shiftKey || event.altKey || event.metaKey) return false;
            if (event.key !== 'ArrowUp' && event.key !== 'ArrowDown') return false;

            const promptArea = this.findPromptArea();
            if (!promptArea || !this.isPromptFocused(promptArea)) return false;

            event.preventDefault();
            event.stopPropagation();

            if (this.promptHistory.length === 0) {
                this.showNotification('No prompt history yet.');
                return true;
            }

            const direction = event.key === 'ArrowUp' ? -1 : 1;
            const maxChars = Math.max(500, Number(this.CONFIG.PROMPT_HISTORY_MAX_CHARS) || 6000);
            if (this.promptHistoryCursor === -1) {
                const draft = this.getPromptText(promptArea);
                if (draft.length > maxChars) {
                    this.promptHistoryDraft = '';
                    this.promptHistoryDraftTooLarge = true;
                } else {
                    this.promptHistoryDraft = draft;
                    this.promptHistoryDraftTooLarge = false;
                }
                this.promptHistoryCursor = this.promptHistory.length;
            }

            let nextCursor = this.promptHistoryCursor;
            while (true) {
                const candidate = nextCursor + direction;
                if (candidate < 0 || candidate > this.promptHistory.length) break;
                if (candidate === this.promptHistory.length) {
                    nextCursor = candidate;
                    break;
                }

                const candidateText = this.promptHistory[candidate] || '';
                if (candidateText.length <= maxChars) {
                    nextCursor = candidate;
                    break;
                }
                nextCursor = candidate;
            }

            if (nextCursor === this.promptHistoryCursor) {
                return true;
            }

            this.promptHistoryCursor = nextCursor;
            if (nextCursor === this.promptHistory.length) {
                if (this.promptHistoryDraftTooLarge) {
                    this.showNotification('Current draft too large to restore via Ctrl up/down.');
                    return true;
                }
                this.setPromptText(this.promptHistoryDraft || '');
            } else {
                this.setPromptText(this.promptHistory[nextCursor] || '');
            }
            return true;
        },

        setQueryAndSend(query, autoSend = false) {
            const applied = this.setPromptText(query);
            if (!applied) return false;
            if (autoSend) {
                this.scheduleSendButtonClick();
            }
            return true;
        },

        scheduleSendButtonClick() {
            const clickIfReady = () => {
                const sendButton = this.findSendButton();
                if (sendButton) {
                    this.capturePromptForHistoryFromPromptArea('auto-send-click');
                    sendButton.click();
                    return true;
                }
                return false;
            };

            if (clickIfReady()) return;

            const observer = new MutationObserver(() => {
                if (clickIfReady()) observer.disconnect();
            });
            observer.observe(document.body, {
                childList: true,
                subtree: true,
                attributes: true,
                attributeFilter: ['disabled', 'aria-disabled']
            });
            setTimeout(() => observer.disconnect(), 5000);
        },

        hasBlockingOpenElements(promptArea) {
            const activeElement = document.activeElement;
            if (this.isEditableElement(activeElement) && !this.isPromptFocused(promptArea)) return true;

            const visible = (el) => {
                const style = window.getComputedStyle(el);
                return style.display !== 'none' && style.visibility !== 'hidden' && style.opacity !== '0';
            };

            const modal = Array.from(document.querySelectorAll('[role="dialog"]')).find(visible);
            if (modal) return true;

            const menu = Array.from(document.querySelectorAll('[role="menu"], [role="listbox"], [data-state="open"]')).find(visible);
            if (menu) return true;

            const editBox = document.querySelector('.bg-token-main-surface-tertiary textarea');
            if (editBox && editBox.offsetParent !== null) return true;

            return false;
        },

        handleGlobalPaste(event) {
            if (!this.isChatGPTPage) return;
            const promptArea = this.findPromptArea();
            if (!promptArea) return;

            if (this.isPromptFocused(promptArea)) {
                if (this.CONFIG.REGULAR_PASTE_ENABLED && this.CONFIG.REGULAR_AUTO_SEND_IN_INPUT) {
                    setTimeout(() => this.scheduleSendButtonClick(), 40);
                }
                return;
            }

            if (!this.CONFIG.GLOBAL_PASTE_ENABLED) return;
            if (this.hasBlockingOpenElements(promptArea)) return;

            const activeElement = document.activeElement;
            if (this.isEditableElement(activeElement) && !this.isPromptFocused(promptArea)) return;

            const pastedText = (event.clipboardData || window.clipboardData).getData('text');
            if (!pastedText || !pastedText.trim()) return;

            if (!this.CONFIG.NICE_AUTO_PASTE_ENABLED && !this.CONFIG.REGULAR_PASTE_ENABLED) return;

            event.preventDefault();
            event.stopPropagation();

            if (this.CONFIG.NICE_AUTO_PASTE_ENABLED) {
                const formattedQuery = `According to NICE guidelines, what is the answer for the following:\n\n${pastedText.trim()}`;
                const success = this.setQueryAndSend(formattedQuery, this.CONFIG.NICE_AUTO_SEND);
                if (success) {
                    this.showNotification(`NICE query pasted${this.CONFIG.NICE_AUTO_SEND ? ' and sent' : ''}.`);
                }
                return;
            }

            if (this.CONFIG.REGULAR_PASTE_ENABLED) {
                const success = this.setPromptText(pastedText);
                if (success) {
                    if (this.CONFIG.REGULAR_AUTO_SEND) {
                        this.scheduleSendButtonClick();
                    }
                    this.showNotification(`Text pasted${this.CONFIG.REGULAR_AUTO_SEND ? ' and sent' : ''}.`);
                }
            }
        },

        handleEnterToSend(event) {
            if (!this.isChatGPTPage || !this.CONFIG.ENTER_TO_SEND_ENABLED) return;
            if (event.key !== 'Enter') return;
            if (event.shiftKey || event.ctrlKey || event.altKey || event.metaKey) return;

            const promptArea = this.findPromptArea();
            if (!promptArea || !this.isPromptFocused(promptArea)) return;

            event.preventDefault();
            const now = Date.now();
            if (now - this.lastEnterPressTime <= this.CONFIG.ENTER_TO_SEND_DOUBLE_PRESS_MS) {
                const sendButton = this.findSendButton();
                if (sendButton) {
                    this.capturePromptForHistoryFromPromptArea('double-enter-send');
                    sendButton.click();
                }
                this.lastEnterPressTime = 0;
                return;
            }
            this.lastEnterPressTime = now;
        },

        boostMediaElement(mediaElement) {
            if (!mediaElement || !this.CONFIG.VOLUME_BOOST_ENABLED) return;
            if (!this.audioContexts.has(mediaElement)) {
                try {
                    const Ctx = window.AudioContext || window.webkitAudioContext;
                    if (!Ctx) return;
                    const ctx = new Ctx();
                    const source = ctx.createMediaElementSource(mediaElement);
                    const gainNode = ctx.createGain();
                    source.connect(gainNode);
                    gainNode.connect(ctx.destination);
                    this.audioContexts.set(mediaElement, { ctx, gainNode });
                } catch (error) {
                    console.warn('Volume boost unavailable for media element:', error);
                    return;
                }
            }

            const audio = this.audioContexts.get(mediaElement);
            if (!audio) return;
            audio.gainNode.gain.value = this.CONFIG.VOLUME_BOOST_LEVEL;
            mediaElement.volume = 1;
            if (audio.ctx.state === 'suspended') {
                audio.ctx.resume().catch(() => {});
            }
        },

        updateVolumeBoostForTrackedMedia() {
            for (const [mediaElement, audio] of this.audioContexts.entries()) {
                if (!mediaElement || !mediaElement.isConnected) {
                    try {
                        if (audio && audio.ctx && typeof audio.ctx.close === 'function') {
                            audio.ctx.close();
                        }
                    } catch (_err) {}
                    this.audioContexts.delete(mediaElement);
                    continue;
                }
                audio.gainNode.gain.value = this.CONFIG.VOLUME_BOOST_ENABLED ? this.CONFIG.VOLUME_BOOST_LEVEL : 1;
            }
        },

        handleMediaElements() {
            const mediaElements = document.querySelectorAll('video, audio');
            mediaElements.forEach((mediaElement) => {
                if (mediaElement.dataset.ttsVolumeBound !== '1') {
                    mediaElement.dataset.ttsVolumeBound = '1';
                    mediaElement.addEventListener('play', () => this.boostMediaElement(mediaElement));
                }
                if (!mediaElement.paused) {
                    this.boostMediaElement(mediaElement);
                }
            });
            this.updateVolumeBoostForTrackedMedia();
        },

        setVolumeBoostEnabled(enabled, silent = false) {
            const nextValue = Boolean(enabled);
            if (this.CONFIG.VOLUME_BOOST_ENABLED === nextValue) return;
            this.CONFIG.VOLUME_BOOST_ENABLED = nextValue;
            if (nextValue) {
                this.handleMediaElements();
            }
            this.updateVolumeBoostForTrackedMedia();
            if (!silent) {
                this.showNotification(`Volume boost ${this.CONFIG.VOLUME_BOOST_ENABLED ? 'on' : 'off'}`);
            }
        },

        setVolumeBoostLevel(level, silent = false) {
            const parsed = Number(level);
            if (!Number.isFinite(parsed)) return;
            const clamped = Math.max(0.1, Math.min(2, parsed));
            this.CONFIG.VOLUME_BOOST_LEVEL = clamped;
            this.updateVolumeBoostForTrackedMedia();
            if (!silent) {
                this.showNotification(`Volume boost ${clamped.toFixed(1)}x`);
            }
        },

        setLowGapMode(enabled, silent = false) {
            const nextValue = Boolean(enabled);
            if (this.CONFIG.LOW_GAP_MODE === nextValue) return;
            this.CONFIG.LOW_GAP_MODE = nextValue;
            if (!silent) {
                this.showNotification(`Low-gap mode ${nextValue ? 'on' : 'off'}`);
            }
        },

        setServerPrecacheMode(enabled, silent = false) {
            const nextValue = Boolean(enabled);
            if (this.CONFIG.SERVER_PRECACHE_MODE === nextValue) return;
            this.CONFIG.SERVER_PRECACHE_MODE = nextValue;
            if (!silent) {
                this.showNotification(`Server precache ${nextValue ? 'on' : 'off'}`);
            }
        },

        normalizeServerQuotePolicy(policy) {
            const next = typeof policy === 'string' ? policy.trim().toLowerCase() : '';
            if (next === 'keep' || next === 'normalize' || next === 'strip') return next;
            return 'strip';
        },

        normalizeServerCustomRemovalMode(mode) {
            const next = typeof mode === 'string' ? mode.trim().toLowerCase() : '';
            if (next === 'exact' || next === 'regex' || next === 'both') return next;
            return 'exact';
        },

        setServerTextNormalizationEnabled(enabled, silent = false) {
            const nextValue = Boolean(enabled);
            if (this.CONFIG.SERVER_TEXT_NORMALIZATION_ENABLED === nextValue) return;
            this.CONFIG.SERVER_TEXT_NORMALIZATION_ENABLED = nextValue;
            if (!silent) {
                this.showNotification(`Server text normalize ${nextValue ? 'on' : 'off'}`);
            }
        },

        setServerQuotePolicy(policy, silent = false) {
            const nextPolicy = this.normalizeServerQuotePolicy(policy);
            if (this.CONFIG.SERVER_QUOTE_POLICY === nextPolicy) return;
            this.CONFIG.SERVER_QUOTE_POLICY = nextPolicy;
            if (!silent) {
                this.showNotification(`Server quote policy: ${nextPolicy}`);
            }
        },

        setServerCustomRemovalMode(mode, silent = false) {
            const nextMode = this.normalizeServerCustomRemovalMode(mode);
            if (this.CONFIG.SERVER_CUSTOM_REMOVAL_MODE === nextMode) return;
            this.CONFIG.SERVER_CUSTOM_REMOVAL_MODE = nextMode;
            if (!silent) {
                this.showNotification(`Server removal mode: ${nextMode}`);
            }
        },

        parseServerRemovalLines(rawValue) {
            if (typeof rawValue !== 'string') return [];
            return rawValue
                .split(/\r?\n/g)
                .map(line => line.trim())
                .filter(line => line.length > 0);
        },

        escapeRegExp(text) {
            return String(text || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        },

        applyServerExactCustomRemovals(text) {
            const rules = this.parseServerRemovalLines(this.CONFIG.SERVER_CUSTOM_EXACT_REMOVALS);
            if (rules.length === 0) return text;

            let output = text;
            for (const rawRule of rules) {
                const escaped = this.escapeRegExp(rawRule).replace(/\s+/g, '\\s+');
                const isWordLike = /^[A-Za-z0-9][A-Za-z0-9\s'-]*[A-Za-z0-9]$/.test(rawRule);
                const pattern = isWordLike
                    ? new RegExp(`\\b${escaped}\\b`, 'gi')
                    : new RegExp(escaped, 'gi');
                output = output.replace(pattern, ' ');
            }
            return output;
        },

        parseServerRegexRule(rawRule) {
            if (typeof rawRule !== 'string') return null;
            const trimmed = rawRule.trim();
            if (!trimmed) return null;

            let source = trimmed;
            let flags = 'gi';
            const slashMatch = trimmed.match(/^\/(.+)\/([a-z]*)$/i);
            if (slashMatch) {
                source = slashMatch[1];
                flags = slashMatch[2] || '';
                if (!flags.includes('g')) flags += 'g';
            }

            try {
                return new RegExp(source, flags);
            } catch (error) {
                this.logPlaybackGuardEvent('server-normalize-invalid-regex', {
                    rule: rawRule,
                    error: String(error && error.message ? error.message : error)
                });
                return null;
            }
        },

        applyServerRegexCustomRemovals(text) {
            const rules = this.parseServerRemovalLines(this.CONFIG.SERVER_CUSTOM_REGEX_REMOVALS);
            if (rules.length === 0) return text;

            let output = text;
            for (const rawRule of rules) {
                const regex = this.parseServerRegexRule(rawRule);
                if (!regex) continue;
                output = output.replace(regex, ' ');
            }
            return output;
        },

        normalizeTextForServerTts(text, context = {}) {
            const source = typeof text === 'string' ? text : '';
            if (!source) return '';
            if (!this.CONFIG.SERVER_TEXT_NORMALIZATION_ENABLED) {
                return source.trim();
            }

            let normalized = source
                .replace(/\r\n/g, '\n')
                .replace(/\u00A0/g, ' ');

            if (this.CONFIG.SERVER_NORMALIZE_PUNCTUATION) {
                normalized = normalized
                    .replace(/[‐‑‒–—]/g, ' - ')
                    .replace(/…/g, '...')
                    .replace(/[•▪◦‣∙]/g, ' ');
            }

            const quotePolicy = this.normalizeServerQuotePolicy(this.CONFIG.SERVER_QUOTE_POLICY);
            if (quotePolicy === 'normalize') {
                normalized = normalized
                    .replace(/[“”„‟«»‹›]/g, '"')
                    .replace(/[‘’‚‛`´]/g, '\'');
            } else if (quotePolicy === 'strip') {
                normalized = normalized
                    .replace(/[“”„‟«»‹›"]/g, ' ')
                    .replace(/[‘’‚‛`´]/g, '\'');
            }

            if (this.CONFIG.SERVER_REMOVE_MARKDOWN_MARKERS) {
                normalized = normalized
                    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/gi, '$1')
                    .replace(/`{1,3}([^`]+)`{1,3}/g, '$1')
                    .replace(/[*_~]+/g, ' ');
            }

            if (this.CONFIG.SERVER_REMOVE_CITATION_MARKERS) {
                normalized = normalized
                    .replace(/\[\s*\d+(?:\s*[,;]\s*\d+)*\s*\]/g, ' ')
                    .replace(/\(\s*(?:source|sources|ref|refs|reference|references)?\s*\d+(?:\s*[,;]\s*\d+)*\s*\)/gi, ' ')
                    .replace(/\+\d+\b/g, ' ');
            }

            const removalMode = this.normalizeServerCustomRemovalMode(this.CONFIG.SERVER_CUSTOM_REMOVAL_MODE);
            if (removalMode === 'exact' || removalMode === 'both') {
                normalized = this.applyServerExactCustomRemovals(normalized);
            }
            if (removalMode === 'regex' || removalMode === 'both') {
                normalized = this.applyServerRegexCustomRemovals(normalized);
            }

            normalized = normalized.replace(/\s+([,.;:!?])/g, '$1');
            if (this.CONFIG.SERVER_NORMALIZE_WHITESPACE) {
                normalized = normalized.replace(/\s+/g, ' ');
            }
            normalized = normalized.trim();

            if (normalized !== source && this.CONFIG.SHOW_DIAGNOSTICS_PANEL) {
                this.logPlaybackGuardEvent('server-text-normalized', {
                    stage: context.stage || null,
                    paragraphIndex: Number.isInteger(context.paragraphIndex) ? context.paragraphIndex : null,
                    sentenceIndex: Number.isInteger(context.sentenceIndex) ? context.sentenceIndex : null,
                    originalLength: source.length,
                    normalizedLength: normalized.length,
                    originalSample: source.slice(0, 120),
                    normalizedSample: normalized.slice(0, 120)
                });
            }

            return normalized;
        },

        getSpeechVolume() {
            if (!this.CONFIG.VOLUME_BOOST_ENABLED) return 0.9;
            const level = Number(this.CONFIG.VOLUME_BOOST_LEVEL);
            if (!Number.isFinite(level)) return 0.9;
            return Math.max(0.1, Math.min(1, level));
        },

        getMaxSynthBacklog() {
            const configured = Math.max(0, Number(this.CONFIG.MAX_SYNTH_BACKLOG) || 0);
            if (!this.CONFIG.LOW_GAP_MODE) return configured;
            return Math.max(configured, 2);
        },

        getSpeechChunkMaxChars() {
            const configured = Math.max(80, Number(this.CONFIG.SPEECH_CHUNK_MAX_CHARS) || 220);
            if (!this.CONFIG.LOW_GAP_MODE) return configured;
            return Math.max(configured, 320);
        },

        getSpeechChunkGapMs() {
            if (this.CONFIG.LOW_GAP_MODE) return 0;
            return Math.max(0, Number(this.CONFIG.SPEECH_CHUNK_GAP_MS) || 0);
        },

        getEffectiveQueueLookahead() {
            const configured = Math.max(0, Math.round(Number(this.CONFIG.QUEUE_LOOKAHEAD) || 0));
            return configured;
        },

