        normalizeHiddenTabPolicy(value) {
            const raw = String(value || '').toLowerCase();
            if (raw === 'never' || raw === 'immediate' || raw === 'delay') return raw;
            return 'delay';
        },

        setHiddenTabPolicy(policy, silent = false) {
            const nextPolicy = this.normalizeHiddenTabPolicy(policy);
            if (this.CONFIG.HIDDEN_TAB_POLICY === nextPolicy) return;
            this.CONFIG.HIDDEN_TAB_POLICY = nextPolicy;
            if (!silent) {
                this.showNotification(`Hidden tab policy: ${nextPolicy}`);
            }
        },

        setAutoPauseHiddenDelayMs(value, silent = false) {
            const parsed = Number(value);
            if (!Number.isFinite(parsed)) return;
            const nextDelay = Math.max(0, Math.round(parsed));
            if (this.CONFIG.AUTO_PAUSE_HIDDEN_DELAY_MS === nextDelay) return;
            this.CONFIG.AUTO_PAUSE_HIDDEN_DELAY_MS = nextDelay;
            if (!silent) {
                this.showNotification(`Hidden pause delay: ${nextDelay} ms`);
            }
        },

        setIdleArrowNavigationEnabled(enabled, silent = false) {
            const nextValue = Boolean(enabled);
            if (this.CONFIG.IDLE_ARROW_NAVIGATION === nextValue) return;
            this.CONFIG.IDLE_ARROW_NAVIGATION = nextValue;
            if (!silent) {
                this.showNotification(`Idle arrow nav ${nextValue ? 'on' : 'off'}`);
            }
        },

        applyOverlayVisibility() {
            const root = document.documentElement;
            if (!root) return;
            root.classList.toggle('tts-overlay-hidden', !this.CONFIG.SHOW_PAGE_OVERLAY);
        },

        setPageOverlayEnabled(enabled, silent = false) {
            const nextValue = Boolean(enabled);
            this.CONFIG.SHOW_PAGE_OVERLAY = nextValue;
            this.applyOverlayVisibility();
            if (!silent && nextValue) {
                this.showNotification('Page overlay on');
            }
        },

        normalizeOverlayPosition(position) {
            if (!position || typeof position !== 'object') return null;
            const left = Number(position.left);
            const top = Number(position.top);
            if (!Number.isFinite(left) || !Number.isFinite(top)) return null;
            return {
                left: Math.round(left),
                top: Math.round(top)
            };
        },

        clampOverlayPosition(position, panel) {
            const margin = 8;
            const width = panel.offsetWidth || 180;
            const height = panel.offsetHeight || 220;
            const maxLeft = Math.max(margin, window.innerWidth - width - margin);
            const maxTop = Math.max(margin, window.innerHeight - height - margin);
            return {
                left: Math.min(Math.max(position.left, margin), maxLeft),
                top: Math.min(Math.max(position.top, margin), maxTop)
            };
        },

        getDefaultOverlayPosition(panel) {
            const margin = 12;
            const width = panel.offsetWidth || 180;
            const height = panel.offsetHeight || 220;
            const candidatePositions = [
                { left: margin, top: 80 },
                { left: window.innerWidth - width - margin, top: 80 },
                { left: margin, top: window.innerHeight - height - margin },
                { left: window.innerWidth - width - margin, top: window.innerHeight - height - margin }
            ];

            let best = this.clampOverlayPosition(candidatePositions[0], panel);
            let bestScore = Number.POSITIVE_INFINITY;
            const sampleSelector = 'p, li, h1, h2, h3, h4, h5, h6, td, th, blockquote, article, [data-message-author-role]';

            for (const candidate of candidatePositions) {
                const clamped = this.clampOverlayPosition(candidate, panel);
                let score = 0;
                const samplePoints = [
                    { x: clamped.left + 20, y: clamped.top + 20 },
                    { x: clamped.left + width - 20, y: clamped.top + 20 },
                    { x: clamped.left + 20, y: clamped.top + height - 20 },
                    { x: clamped.left + width - 20, y: clamped.top + height - 20 },
                    { x: clamped.left + width / 2, y: clamped.top + height / 2 }
                ];
                for (const point of samplePoints) {
                    const x = Math.max(0, Math.min(window.innerWidth - 1, point.x));
                    const y = Math.max(0, Math.min(window.innerHeight - 1, point.y));
                    const hit = document.elementFromPoint(x, y);
                    if (!hit) continue;
                    if (hit.closest('[data-tts-ui]')) continue;
                    if (hit.matches(sampleSelector) || hit.closest(sampleSelector)) {
                        score += 2;
                    } else if ((hit.textContent || '').trim().length > 0) {
                        score += 1;
                    }
                }
                if (score < bestScore) {
                    bestScore = score;
                    best = clamped;
                }
            }

            return best;
        },

        applyOverlayPanelPosition(position = null) {
            const panel = this.overlayPanel || document.getElementById('tts-control-panel');
            if (!panel) return;
            const normalized = this.normalizeOverlayPosition(position);
            const target = normalized || this.getDefaultOverlayPosition(panel);
            const clamped = this.clampOverlayPosition(target, panel);
            panel.style.left = `${clamped.left}px`;
            panel.style.top = `${clamped.top}px`;
            this.CONFIG.OVERLAY_POSITION = normalized ? clamped : null;
        },

        setOverlayPosition(position, options = {}) {
            const normalized = this.normalizeOverlayPosition(position);
            this.CONFIG.OVERLAY_POSITION = normalized;
            this.applyOverlayPanelPosition(normalized);
            if (options.persist === true) {
                persistProfileSetting(this.settingsProfile || getCurrentProfile(), 'overlayPosition', normalized);
            }
            if (!options.silent) {
                this.showNotification(normalized ? 'Overlay position saved' : 'Overlay position reset');
            }
        },

        toggleWordHighlight() {
            this.setWordHighlightEnabled(!this.CONFIG.WORD_HIGHLIGHT_ENABLED);
        },

        findWordIndexByChar(charIndex) {
            const spans = this.processedParagraph.wordSpans;
            const offsets = this.processedParagraph.wordOffsets;
            if (!spans || !offsets || offsets.length === 0) return -1;

            let low = 0;
            let high = offsets.length - 1;
            while (low <= high) {
                const mid = (low + high) >> 1;
                if (offsets[mid] <= charIndex) {
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }

            const idx = high;
            if (idx < 0) return -1;
            const start = offsets[idx];
            const end = start + spans[idx].textContent.length;
            if (charIndex < start || charIndex > end) return -1;
            return idx;
        },

        highlightCurrentWord(event) {
            if (!this.CONFIG.WORD_HIGHLIGHT_ENABLED || !this.wordHighlightActiveForCurrent) return;
            if (event.name !== 'word') return;
            if (this.currentWordSpan) {
                this.currentWordSpan.classList.remove('tts-current-word');
                this.currentWordSpan = null;
            }

            const baseOffset = Number.isFinite(this.currentUtteranceStartOffset) ? this.currentUtteranceStartOffset : 0;
            const idx = this.findWordIndexByChar((event.charIndex || 0) + baseOffset);
            if (idx === -1) return;
            const span = this.processedParagraph.wordSpans[idx];
            if (!span) return;
            span.classList.add('tts-current-word');
            this.currentWordSpan = span;
        },

        describeSpeechErrorEvent(event) {
            if (!event) return {};
            return {
                type: event.type || null,
                error: event.error || null,
                name: event.name || null,
                charIndex: Number.isFinite(event.charIndex) ? event.charIndex : null,
                elapsedTime: Number.isFinite(event.elapsedTime) ? event.elapsedTime : null,
                utteranceTextLength: event.utterance && event.utterance.text ? event.utterance.text.length : null
            };
        },

        logSpeechSynthesisError(context, event, extra = {}) {
            if (!this.CONFIG.SHOW_DIAGNOSTICS_PANEL) return;
            const synth = this.speechSynthesis;
            const eventInfo = this.describeSpeechErrorEvent(event);
            const paragraph = Number.isInteger(extra.index) ? this.paragraphsList[extra.index] : null;
            const paragraphText = paragraph && paragraph.text ? paragraph.text : '';
            const payload = {
                context,
                url: window.location && window.location.href ? window.location.href : '',
                event: eventInfo,
                synthState: {
                    speaking: Boolean(synth && synth.speaking),
                    pending: Boolean(synth && synth.pending),
                    paused: Boolean(synth && synth.paused)
                },
                ttsState: {
                    ttsActive: this.ttsActive,
                    continuousReadingActive: this.continuousReadingActive,
                    isPaused: this.isPaused,
                    currentParagraphIndex: this.currentParagraphIndex,
                    queueSize: this.queuedParagraphs.size,
                    paragraphsCount: this.paragraphsList.length
                },
                guardState: {
                    visibility: document.visibilityState,
                    lockOwned: this.playbackLockOwned,
                    ownerId: this.playbackOwnerId,
                    pausedForHiddenTab: this.pausedForHiddenTab,
                    hiddenTabPolicy: this.CONFIG.HIDDEN_TAB_POLICY,
                    hiddenPauseDelayMs: this.CONFIG.AUTO_PAUSE_HIDDEN_DELAY_MS,
                    retryCountForIndex: Number.isInteger(extra.index)
                        ? Number(this.interruptedRetryAttempts.get(extra.index) || 0)
                        : 0
                },
                utterance: {
                    index: Number.isInteger(extra.index) ? extra.index : null,
                    voiceName: extra.voiceName || null,
                    voiceLang: extra.voiceLang || null,
                    rate: Number.isFinite(extra.rate) ? extra.rate : null,
                    textLength: typeof extra.text === 'string' ? extra.text.length : null,
                    textSample: typeof extra.text === 'string' ? extra.text.slice(0, 160) : null
                },
                paragraph: paragraph ? {
                    textLength: paragraphText.length,
                    textSample: paragraphText.slice(0, 160)
                } : null
            };

            const nonFatal = eventInfo.error === 'interrupted' || eventInfo.error === 'canceled';
            if (nonFatal) {
                console.warn('[TTS] Speech synthesis interruption', payload);
            } else {
                console.error('[TTS] Speech synthesis error', payload);
            }

            try {
                const jsonPayload = JSON.stringify(payload, null, 2);
                console.log(`[TTS] Speech synthesis diagnostics JSON (${context})\n${jsonPayload}`);
            } catch (_error) {
                console.warn('[TTS] Failed to serialize diagnostics payload');
            }
        },

        triggerTTS(text, onComplete = null) {
            if (!text || text.length === 0) {
                if (onComplete) onComplete();
                return;
            }
            this.requestPlaybackLock('start-noncontinuous', (granted) => {
                if (!granted) return;

                if (this.isServerVoiceSelected()) {
                    this.playServerSingleUtterance(text, onComplete);
                    return;
                }

                this.ttsActive = true;
                this.isPaused = false;
                const utterance = new SpeechSynthesisUtterance(text);
                utterance.__tmxSessionId = this.playbackSessionId;
                const preferredVoice = this.resolvePreferredVoice();
                if (preferredVoice) utterance.voice = preferredVoice;
                utterance.rate = this.getSafeSpeechRate(preferredVoice);
                utterance.volume = this.getSpeechVolume();

                if (this.CONFIG.WORD_HIGHLIGHT_ENABLED) {
                    utterance.onboundary = (event) => {
                        if (this.isStaleUtterance(utterance)) return;
                        this.highlightCurrentWord(event);
                    };
                }

                utterance.onend = () => {
                    if (this.isStaleUtterance(utterance)) {
                        this.logPlaybackGuardEvent('stale-utterance-ignored', { phase: 'triggerTTS.onend' });
                        return;
                    }
                    this.ttsActive = false;
                    if (onComplete && this.continuousReadingActive) {
                        onComplete();
                    } else {
                        this.stopTTS(false);
                    }
                };
                utterance.onerror = (e) => {
                    if (this.isStaleUtterance(utterance)) {
                        this.logPlaybackGuardEvent('stale-utterance-ignored', { phase: 'triggerTTS.onerror' });
                        return;
                    }
                    this.logSpeechSynthesisError('triggerTTS', e, {
                        text,
                        rate: utterance.rate,
                        voiceName: utterance.voice ? utterance.voice.name : null,
                        voiceLang: utterance.voice ? utterance.voice.lang : null
                    });
                    this.ttsActive = false;
                    this.revertParagraph();
                    if (onComplete && this.continuousReadingActive) onComplete();
                };

                this.speechSynthesis.speak(utterance);
            });
        },

        cancelActiveSpeechQueue(reason = 'queue-reset') {
            if (this.speechSynthesis.speaking || this.speechSynthesis.pending) {
                this.logPlaybackGuardEvent('speech-queue-cancel', {
                    reason,
                    speaking: Boolean(this.speechSynthesis.speaking),
                    pending: Boolean(this.speechSynthesis.pending),
                    queuedParagraphs: this.queuedParagraphs.size
                });
                this.speechSynthesis.cancel();
            }
        },

        splitSpeechChunk(text, startOffset = 0) {
            const source = typeof text === 'string' ? text.trim() : '';
            if (!source) {
                return { chunkText: '', remainderText: '', nextStartOffset: startOffset };
            }

            const maxChars = this.getSpeechChunkMaxChars();
            if (source.length <= maxChars) {
                return {
                    chunkText: source,
                    remainderText: '',
                    nextStartOffset: startOffset + source.length + 1
                };
            }

            let splitAt = source.lastIndexOf(' ', maxChars);
            if (splitAt < Math.floor(maxChars * 0.6)) {
                splitAt = maxChars;
            }

            const chunkText = source.slice(0, splitAt).trim();
            const remainderText = source.slice(splitAt).trim();
            return {
                chunkText,
                remainderText,
                nextStartOffset: startOffset + chunkText.length + 1
            };
        },

        getChunkedSpeechForIndex(index, baseText, baseStartOffset = 0) {
            const pendingChunk = this.chunkedParagraphState.get(index);
            let sourceText = baseText;
            let sourceOffset = baseStartOffset;

            if (pendingChunk && typeof pendingChunk.text === 'string' && pendingChunk.text.trim()) {
                sourceText = pendingChunk.text;
                sourceOffset = Number.isFinite(pendingChunk.startOffset)
                    ? pendingChunk.startOffset
                    : sourceOffset;
            }

            const split = this.splitSpeechChunk(sourceText, sourceOffset);
            if (!split.chunkText) {
                this.chunkedParagraphState.delete(index);
                return { utteranceText: '', startOffset: sourceOffset };
            }

            if (split.remainderText) {
                this.chunkedParagraphState.set(index, {
                    text: split.remainderText,
                    startOffset: split.nextStartOffset
                });
            } else {
                this.chunkedParagraphState.delete(index);
            }

            return {
                utteranceText: split.chunkText,
                startOffset: sourceOffset
            };
        },

        splitTextIntoSentences(text) {
            const source = typeof text === 'string' ? text : '';
            if (!source.trim()) return [];
            const regex = /[^.!?]+[.!?]*/g;
            const result = [];
            let match;
            while ((match = regex.exec(source)) !== null) {
                const original = match[0];
                const trimmed = original.trim();
                if (!trimmed) continue;
                const leadingWs = original.length - original.trimStart().length;
                const startOffset = match.index + leadingWs;
                result.push({
                    text: trimmed,
                    startOffset
                });
            }
            if (result.length === 0) {
                result.push({
                    text: source.trim(),
                    startOffset: 0
                });
            }
            return result;
        },

        buildServerSentencePlan(paragraphText, startOffset = 0, context = {}) {
            const safeStart = Math.max(0, Math.floor(Number(startOffset) || 0));
            const source = typeof paragraphText === 'string' ? paragraphText : '';
            const sliced = source.slice(safeStart);
            const sentences = this.splitTextIntoSentences(sliced);
            const plan = [];
            for (const sentence of sentences) {
                const normalizedSentence = this.normalizeTextForServerTts(sentence.text, {
                    stage: 'sentence-plan',
                    paragraphIndex: Number.isInteger(context.paragraphIndex) ? context.paragraphIndex : null
                });
                if (!normalizedSentence) continue;
                plan.push({
                    text: normalizedSentence,
                    startOffset: safeStart + sentence.startOffset
                });
            }
            return plan;
        },

        getServerSentenceCacheKey(state, sentenceIndex) {
            return `${state.playbackSessionId}:${state.paragraphIndex}:${sentenceIndex}`;
        },

        clearServerSentenceCache() {
            for (const payload of this.serverSentenceAudioCache.values()) {
                if (payload && payload.wavUrl) {
                    URL.revokeObjectURL(payload.wavUrl);
                }
            }
            this.serverSentenceAudioCache.clear();
            this.serverSentenceAudioInflight.clear();
        },

        stopServerAudioPlayback() {
            if (!this.serverAudioElement) return;
            try {
                this.serverAudioElement.pause();
                this.serverAudioElement.src = '';
                this.serverAudioElement.load();
            } catch (_error) {
                // Ignore cleanup errors when the element is already detached.
            }
            this.serverAudioElement = null;
        },

        base64ToUint8Array(base64) {
            const binary = atob(base64 || '');
            const bytes = new Uint8Array(binary.length);
            for (let i = 0; i < binary.length; i++) {
                bytes[i] = binary.charCodeAt(i);
            }
            return bytes;
        },

        createWavUrlFromPcm(pcmBytes, sampleRate) {
            const safeSampleRate = Number.isFinite(Number(sampleRate))
                ? Math.max(8000, Math.round(Number(sampleRate)))
                : this.CONFIG.SERVER_TTS_SAMPLE_RATE;
            const channels = 1;
            const bitsPerSample = 16;
            const blockAlign = channels * (bitsPerSample / 8);
            const byteRate = safeSampleRate * blockAlign;
            const dataSize = pcmBytes.length;
            const buffer = new ArrayBuffer(44 + dataSize);
            const view = new DataView(buffer);
            const writeString = (offset, value) => {
                for (let i = 0; i < value.length; i++) {
                    view.setUint8(offset + i, value.charCodeAt(i));
                }
            };
            writeString(0, 'RIFF');
            view.setUint32(4, 36 + dataSize, true);
            writeString(8, 'WAVE');
            writeString(12, 'fmt ');
            view.setUint32(16, 16, true);
            view.setUint16(20, 1, true);
            view.setUint16(22, channels, true);
            view.setUint32(24, safeSampleRate, true);
            view.setUint32(28, byteRate, true);
            view.setUint16(32, blockAlign, true);
            view.setUint16(34, bitsPerSample, true);
            writeString(36, 'data');
            view.setUint32(40, dataSize, true);
            new Uint8Array(buffer, 44).set(pcmBytes);
            const blob = new Blob([buffer], { type: 'audio/wav' });
            return URL.createObjectURL(blob);
        },

        async fetchServerSentenceAudio(state, sentenceIndex) {
            const sentence = state.sentences[sentenceIndex];
            if (!sentence || !sentence.text) {
                throw new Error('Missing sentence');
            }
            const selectedVoiceId = this.getSelectedServerVoiceId();
            if (!selectedVoiceId) {
                throw new Error('No server voice selected');
            }

            const speedRaw = Number(this.CONFIG.SPEECH_RATE);
            const safeSpeed = Number.isFinite(speedRaw) ? Math.max(0.25, Math.min(4, speedRaw)) : 2.0;
            const response = await this.sendRuntimeMessageAsync({
                action: 'synthesizeServerTts',
                baseUrl: this.normalizeServerBaseUrl(this.CONFIG.SERVER_BASE_URL),
                text: sentence.text,
                voiceId: selectedVoiceId,
                speed: safeSpeed
            });
            if (!response || response.ok !== true || typeof response.pcmBase64 !== 'string') {
                const error = response && response.error ? response.error : 'Server synthesis failed';
                throw new Error(error);
            }

            const pcmBytes = this.base64ToUint8Array(response.pcmBase64);
            const wavUrl = this.createWavUrlFromPcm(pcmBytes, response.sampleRate);
            if (state.playbackSessionId !== this.playbackSessionId) {
                URL.revokeObjectURL(wavUrl);
                throw new Error('Stale server audio');
            }
            return {
                wavUrl,
                sampleRate: response.sampleRate,
                audioLength: response.audioLength
            };
        },

        async getOrFetchServerSentenceAudio(state, sentenceIndex) {
            const key = this.getServerSentenceCacheKey(state, sentenceIndex);
            if (this.serverSentenceAudioCache.has(key)) {
                return this.serverSentenceAudioCache.get(key);
            }
            if (this.serverSentenceAudioInflight.has(key)) {
                return this.serverSentenceAudioInflight.get(key);
            }
            const fetchPromise = this.fetchServerSentenceAudio(state, sentenceIndex)
                .then((payload) => {
                    this.serverSentenceAudioInflight.delete(key);
                    this.serverSentenceAudioCache.set(key, payload);
                    return payload;
                })
                .catch((error) => {
                    this.serverSentenceAudioInflight.delete(key);
                    throw error;
                });
            this.serverSentenceAudioInflight.set(key, fetchPromise);
            return fetchPromise;
        },

        primeNextServerSentence(state, currentSentenceIndex) {
            if (!this.CONFIG.SERVER_PRECACHE_MODE) return;
            const nextIndex = currentSentenceIndex + 1;
            if (nextIndex >= state.sentences.length) return;
            this.getOrFetchServerSentenceAudio(state, nextIndex).catch((error) => {
                this.logPlaybackGuardEvent('server-precache-failed', {
                    paragraphIndex: state.paragraphIndex,
                    sentenceIndex: nextIndex,
                    error: String(error && error.message ? error.message : error)
                });
            });
        },

        async playServerSentence(state, sentenceIndex) {
            if (!this.continuousReadingActive) return;
            if (state.playbackSessionId !== this.playbackSessionId) return;
            if (sentenceIndex >= state.sentences.length) {
                this.onServerParagraphComplete(state);
                return;
            }

            state.sentenceIndex = sentenceIndex;
            const sentence = state.sentences[sentenceIndex];
            this.currentUtteranceStartOffset = sentence.startOffset;
            this.ttsActive = true;
            this.isPaused = false;
            this.pausedForHiddenTab = false;

            const startTime = performance.now();
            this.lastGapMs = this.lastUtteranceEndTime ? startTime - this.lastUtteranceEndTime : null;
            this.updateDiagnosticsPanel();

            let payload;
            try {
                payload = await this.getOrFetchServerSentenceAudio(state, sentenceIndex);
            } catch (error) {
                this.logPlaybackGuardEvent('server-sentence-fetch-error', {
                    paragraphIndex: state.paragraphIndex,
                    sentenceIndex,
                    error: String(error && error.message ? error.message : error)
                });
                this.ttsActive = false;
                this.currentUtteranceStartOffset = 0;
                this.lastUtteranceEndTime = performance.now();
                this.playServerSentence(state, sentenceIndex + 1);
                return;
            }

            if (state.playbackSessionId !== this.playbackSessionId || !this.continuousReadingActive) return;

            this.stopServerAudioPlayback();
            const audio = new Audio(payload.wavUrl);
            audio.preload = 'auto';
            this.serverAudioElement = audio;
            this.primeNextServerSentence(state, sentenceIndex);

            audio.onended = () => {
                if (state.playbackSessionId !== this.playbackSessionId) return;
                this.serverAudioElement = null;
                this.ttsActive = false;
                this.currentUtteranceStartOffset = 0;
                this.lastUtteranceEndTime = performance.now();
                this.playServerSentence(state, sentenceIndex + 1);
            };
            audio.onerror = () => {
                if (state.playbackSessionId !== this.playbackSessionId) return;
                this.logPlaybackGuardEvent('server-audio-play-error', {
                    paragraphIndex: state.paragraphIndex,
                    sentenceIndex
                });
                this.serverAudioElement = null;
                this.ttsActive = false;
                this.currentUtteranceStartOffset = 0;
                this.lastUtteranceEndTime = performance.now();
                this.playServerSentence(state, sentenceIndex + 1);
            };

            audio.play().catch((error) => {
                if (state.playbackSessionId !== this.playbackSessionId) return;
                this.logPlaybackGuardEvent('server-audio-play-rejected', {
                    paragraphIndex: state.paragraphIndex,
                    sentenceIndex,
                    error: String(error && error.message ? error.message : error)
                });
                this.serverAudioElement = null;
                this.ttsActive = false;
                this.currentUtteranceStartOffset = 0;
                this.lastUtteranceEndTime = performance.now();
                this.playServerSentence(state, sentenceIndex + 1);
            });
        },

        startServerPlaybackFromParagraph(index, options = {}) {
            if (!this.continuousReadingActive) return;

            this.stopServerAudioPlayback();
            this.clearServerSentenceCache();
            this.cancelActiveSpeechQueue('server-voice-start');
            this.queuedParagraphs.clear();
            this.queuedStartOffsets.clear();
            this.chunkedParagraphState.clear();
            clearTimeout(this.chunkContinuationTimeoutId);
            this.chunkContinuationTimeoutId = null;

            if (index < 0 || index >= this.paragraphsList.length) {
                this.stopTTS(false);
                return;
            }

            const para = this.paragraphsList[index];
            if (!para || !para.element || !para.text) {
                this.stopTTS(false);
                return;
            }

            const startCharIndex = Number(options && options.startCharIndex);
            const safeStartChar = Number.isFinite(startCharIndex) ? Math.max(0, Math.floor(startCharIndex)) : 0;
            const sentences = this.buildServerSentencePlan(para.text, safeStartChar, { paragraphIndex: index });
            if (sentences.length === 0) {
                const nextIndex = index + 1;
                if (nextIndex < this.paragraphsList.length) {
                    this.startServerPlaybackFromParagraph(nextIndex, {});
                } else {
                    this.stopTTS(false);
                }
                return;
            }

            this.currentParagraphIndex = index;
            this.lastSpokenElement = para.element;
            this.wordHighlightActiveForCurrent = false;
            this.clearHighlights(true);
            para.element.classList.add('tts-current-sentence');
            this.updateProgressPanel();

            if (this.pointerLoopId) cancelAnimationFrame(this.pointerLoopId);
            this.updatePointerArrow();

            const state = {
                playbackSessionId: this.playbackSessionId,
                paragraphIndex: index,
                sentences,
                sentenceIndex: 0
            };
            this.serverPlaybackState = state;
            this.playServerSentence(state, 0);
        },

        onServerParagraphComplete(state) {
            if (!this.continuousReadingActive) return;
            if (!state || state.playbackSessionId !== this.playbackSessionId) return;

            this.clearHighlights(true);
            this.deferProcessedParagraphRevert();
            this.updateProgressPanel();

            const refreshedIndex = this.refreshParagraphIndex(state.paragraphIndex);
            const lastIndex = this.paragraphsList.length - 1;
            if (refreshedIndex >= lastIndex) {
                if (!this.isChatGPTPage) {
                    if (this.CONFIG.LOOP_ON_END) {
                        this.loopToTop();
                    } else {
                        this.stopTTS(false);
                        this.showNotification('End of page.');
                    }
                    return;
                }
                const nextIndex = refreshedIndex + 1;
                this.waitForMoreParagraphs(nextIndex);
                return;
            }

            this.startServerPlaybackFromParagraph(refreshedIndex + 1, {});
        },

        async playServerSingleUtterance(text, onComplete = null) {
            const selectedVoiceId = this.getSelectedServerVoiceId();
            if (!selectedVoiceId) {
                if (onComplete) onComplete();
                return;
            }

            const normalizedText = this.normalizeTextForServerTts(text, { stage: 'single-utterance' });
            if (!normalizedText) {
                if (onComplete) onComplete();
                return;
            }

            this.advancePlaybackSession('server-single-utterance');
            this.stopServerAudioPlayback();
            this.clearServerSentenceCache();
            this.ttsActive = true;
            this.isPaused = false;

            const speedRaw = Number(this.CONFIG.SPEECH_RATE);
            const safeSpeed = Number.isFinite(speedRaw) ? Math.max(0.25, Math.min(4, speedRaw)) : 2.0;
            let response;
            try {
                response = await this.sendRuntimeMessageAsync({
                    action: 'synthesizeServerTts',
                    baseUrl: this.normalizeServerBaseUrl(this.CONFIG.SERVER_BASE_URL),
                    text: normalizedText,
                    voiceId: selectedVoiceId,
                    speed: safeSpeed
                });
            } catch (error) {
                this.logPlaybackGuardEvent('server-single-fetch-failed', {
                    error: String(error && error.message ? error.message : error)
                });
                this.ttsActive = false;
                if (onComplete) onComplete();
                return;
            }

            if (!response || response.ok !== true || typeof response.pcmBase64 !== 'string') {
                this.logPlaybackGuardEvent('server-single-invalid-response', {
                    error: response && response.error ? response.error : null
                });
                this.ttsActive = false;
                if (onComplete) onComplete();
                return;
            }

            const pcmBytes = this.base64ToUint8Array(response.pcmBase64);
            const wavUrl = this.createWavUrlFromPcm(pcmBytes, response.sampleRate);
            const sessionId = this.playbackSessionId;
            if (sessionId !== this.playbackSessionId) {
                URL.revokeObjectURL(wavUrl);
                return;
            }

            const audio = new Audio(wavUrl);
            audio.preload = 'auto';
            this.serverAudioElement = audio;
            audio.onended = () => {
                URL.revokeObjectURL(wavUrl);
                if (sessionId !== this.playbackSessionId) return;
                this.serverAudioElement = null;
                this.ttsActive = false;
                if (onComplete && this.continuousReadingActive) {
                    onComplete();
                } else {
                    this.stopTTS(false);
                }
            };
            audio.onerror = () => {
                URL.revokeObjectURL(wavUrl);
                if (sessionId !== this.playbackSessionId) return;
                this.serverAudioElement = null;
                this.ttsActive = false;
                if (onComplete && this.continuousReadingActive) onComplete();
            };
            audio.play().catch(() => {
                URL.revokeObjectURL(wavUrl);
                if (sessionId !== this.playbackSessionId) return;
                this.serverAudioElement = null;
                this.ttsActive = false;
                if (onComplete && this.continuousReadingActive) onComplete();
            });
        },

        enqueueParagraph(index) {
            if (!this.continuousReadingActive) return;
            if (this.paragraphsDirty) {
                this.refreshParagraphsIfNeeded(true);
            }
            if (index < 0 || index >= this.paragraphsList.length) return;
            if (this.queuedParagraphs.has(index)) return;

            const para = this.paragraphsList[index];
            if (!para || !para.element || !para.text) return;

            const maxBacklog = this.getMaxSynthBacklog();
            const bufferedAhead = this.queuedParagraphs.size;
            const synthBusy = Boolean(this.speechSynthesis.speaking || this.speechSynthesis.pending);
            if (synthBusy && bufferedAhead > maxBacklog) {
                this.logPlaybackGuardEvent('backlog-guard-skip', {
                    index,
                    bufferedAhead,
                    maxBacklog
                });
                return;
            }

            let utteranceText = para.text;
            let startOffset = 0;
            if (this.queuedStartOffsets.has(index)) {
                const requestedOffset = Number(this.queuedStartOffsets.get(index));
                this.queuedStartOffsets.delete(index);
                if (Number.isFinite(requestedOffset)) {
                    const safeOffset = Math.max(0, Math.min(utteranceText.length - 1, Math.floor(requestedOffset)));
                    const sliced = utteranceText.slice(safeOffset);
                    const leadingWhitespaceLength = (sliced.match(/^\s+/) || [''])[0].length;
                    const normalizedOffset = safeOffset + leadingWhitespaceLength;
                    const normalizedSlice = utteranceText.slice(normalizedOffset);
                    if (normalizedSlice.trim().length > 0) {
                        utteranceText = normalizedSlice;
                        startOffset = normalizedOffset;
                    }
                }
            }

            if (!utteranceText || !utteranceText.trim()) return;

            const chunked = this.getChunkedSpeechForIndex(index, utteranceText, startOffset);
            utteranceText = chunked.utteranceText;
            startOffset = chunked.startOffset;
            if (!utteranceText || !utteranceText.trim()) return;

            const utterance = new SpeechSynthesisUtterance(utteranceText);
            const preferredVoice = this.resolvePreferredVoice();
            if (preferredVoice) utterance.voice = preferredVoice;
            utterance.rate = this.getSafeSpeechRate(preferredVoice);
            utterance.volume = this.getSpeechVolume();
            utterance.__tmxStartOffset = startOffset;
            utterance.__tmxSessionId = this.playbackSessionId;

            utterance.onstart = () => this.onUtteranceStart(index, utterance);
            if (this.CONFIG.WORD_HIGHLIGHT_ENABLED) {
                utterance.onboundary = (event) => {
                    if (this.isStaleUtterance(utterance)) return;
                    this.highlightCurrentWord(event);
                };
            }
            utterance.onend = () => this.onUtteranceEnd(index, utterance);
            utterance.onerror = (e) => this.onUtteranceError(index, e, utterance);

            this.queuedParagraphs.add(index);
            this.speechSynthesis.speak(utterance);
        },

        queueFromIndex(startIndex, options = {}) {
            this.advancePlaybackSession('queue-from-index');
            this.cancelActiveSpeechQueue('queue-from-index');
            this.queuedParagraphs.clear();
            this.queuedStartOffsets.clear();
            this.chunkedParagraphState.clear();
            clearTimeout(this.chunkContinuationTimeoutId);
            this.chunkContinuationTimeoutId = null;
            if (this.paragraphsDirty) {
                this.refreshParagraphsIfNeeded(true);
            }

            const requestedStartCharIndex = Number(options && options.startCharIndex);
            if (Number.isFinite(requestedStartCharIndex) && requestedStartCharIndex > 0) {
                this.queuedStartOffsets.set(startIndex, requestedStartCharIndex);
            }

            const effectiveLookahead = this.getEffectiveQueueLookahead();

            this.logPlaybackGuardEvent('queue-from-index', {
                playbackSessionId: this.playbackSessionId,
                startIndex,
                startCharIndex: Number.isFinite(requestedStartCharIndex) ? requestedStartCharIndex : null,
                lookahead: this.CONFIG.QUEUE_LOOKAHEAD,
                effectiveLookahead,
                serverPrecacheMode: this.CONFIG.SERVER_PRECACHE_MODE
            });

            this.enqueueParagraph(startIndex);
            if (this.chunkedParagraphState.has(startIndex) || effectiveLookahead <= 0) {
                return;
            }

            const maxIndex = Math.min(this.paragraphsList.length - 1, startIndex + effectiveLookahead);
            for (let i = startIndex + 1; i <= maxIndex; i++) {
                this.enqueueParagraph(i);
                if (this.chunkedParagraphState.has(i)) {
                    break;
                }
            }
        },

        onUtteranceStart(index, utterance = null) {
            if (this.isStaleUtterance(utterance)) {
                this.logPlaybackGuardEvent('stale-utterance-ignored', {
                    phase: 'queued.onstart',
                    index,
                    utteranceSessionId: utterance ? utterance.__tmxSessionId : null
                });
                return;
            }
            this.ttsActive = true;
            this.isPaused = false;
            this.pausedForHiddenTab = false;
            const startOffset = utterance && Number.isFinite(utterance.__tmxStartOffset)
                ? Number(utterance.__tmxStartOffset)
                : 0;
            this.currentUtteranceStartOffset = Math.max(0, startOffset);
            this.interruptedRetryAttempts.delete(index);

            const startTime = performance.now();
            this.lastGapMs = this.lastUtteranceEndTime ? startTime - this.lastUtteranceEndTime : null;

            this.currentParagraphIndex = index;
            const para = this.paragraphsList[index];
            if (!para || !para.element) return;

            this.wordHighlightActiveForCurrent = this.shouldHighlightWordsForElement(para.element);
            this.lastSpokenElement = para.element;
            this.startAutoScroll();
            this.maybeAutoScrollOnStart();

            const wrapStart = performance.now();
            const textToRead = this.prepareParagraphForReading(para.element);
            this.lastWrapMs = performance.now() - wrapStart;
            this.updateDiagnosticsPanel();
            this.updateProgressPanel();
            if (!textToRead) return;

            this.clearHighlights(true);
            para.element.classList.add('tts-current-sentence');

            if (this.pointerLoopId) cancelAnimationFrame(this.pointerLoopId);
            this.updatePointerArrow();
            this.prewrapNextParagraph(index);
            if (!this.chunkedParagraphState.has(index)) {
                this.prewarmNextUtterance(index);
            }
        },

        onUtteranceEnd(index, utterance = null) {
            if (this.isStaleUtterance(utterance)) {
                this.logPlaybackGuardEvent('stale-utterance-ignored', {
                    phase: 'queued.onend',
                    index,
                    utteranceSessionId: utterance ? utterance.__tmxSessionId : null
                });
                return;
            }
            this.ttsActive = false;
            this.currentUtteranceStartOffset = 0;
            this.queuedParagraphs.delete(index);
            this.lastUtteranceEndTime = performance.now();
            this.clearHighlights(true);
            this.deferProcessedParagraphRevert();

            if (!this.continuousReadingActive) return;

            if (this.chunkedParagraphState.has(index)) {
                const hasFutureQueuedSpeech = this.queuedParagraphs.size > 0 || Boolean(this.speechSynthesis.pending);
                if (hasFutureQueuedSpeech) {
                    this.advancePlaybackSession('chunk-continuation-priority');
                    this.cancelActiveSpeechQueue('chunk-continuation-priority');
                    this.queuedParagraphs.clear();
                    this.queuedStartOffsets.clear();
                }
                const gapMs = this.getSpeechChunkGapMs();
                clearTimeout(this.chunkContinuationTimeoutId);
                this.chunkContinuationTimeoutId = setTimeout(() => {
                    this.chunkContinuationTimeoutId = null;
                    if (!this.continuousReadingActive) return;
                    this.enqueueParagraph(index);
                }, gapMs);
                return;
            }

            const refreshedIndex = this.refreshParagraphIndex(index);
            const lastIndex = this.paragraphsList.length - 1;
            if (refreshedIndex >= lastIndex) {
                if (!this.isChatGPTPage) {
                    if (this.CONFIG.LOOP_ON_END) {
                        this.loopToTop();
                    } else {
                        this.stopTTS(false);
                        this.showNotification('End of page.');
                    }
                    return;
                }
                const nextIndex = refreshedIndex + 1;
                this.waitForMoreParagraphs(nextIndex);
                return;
            }

            if (this.queuedParagraphs.size === 0) {
                const nextIndex = refreshedIndex + 1;
                this.enqueueParagraph(nextIndex);
            }
        },

        onUtteranceError(index, error, utterance = null) {
            if (this.isStaleUtterance(utterance)) {
                this.logPlaybackGuardEvent('stale-utterance-ignored', {
                    phase: 'queued.onerror',
                    index,
                    utteranceSessionId: utterance ? utterance.__tmxSessionId : null
                });
                return;
            }
            this.logSpeechSynthesisError('queuedParagraph', error, {
                index,
                text: utterance && typeof utterance.text === 'string' ? utterance.text : null,
                rate: utterance && Number.isFinite(utterance.rate) ? utterance.rate : this.CONFIG.SPEECH_RATE,
                voiceName: utterance && utterance.voice ? utterance.voice.name : null,
                voiceLang: utterance && utterance.voice ? utterance.voice.lang : null
            });

            if (this.shouldRetryInterruptedUtterance(error, index)) {
                const retryDelay = Math.max(50, Number(this.CONFIG.INTERRUPTED_RETRY_DELAY_MS) || 250);
                this.logPlaybackGuardEvent('interrupted-retry', { index, retryDelay });
                this.queuedParagraphs.delete(index);
                setTimeout(() => {
                    if (!this.continuousReadingActive) return;
                    this.enqueueParagraph(index);
                }, retryDelay);
                return;
            }

            this.ttsActive = false;
            this.currentUtteranceStartOffset = 0;
            this.queuedParagraphs.delete(index);
            this.chunkedParagraphState.delete(index);
            this.flushPendingReverts();
            this.revertParagraph();
            if (!this.continuousReadingActive) return;

            const nextIndex = index + 1;
            this.enqueueParagraph(nextIndex);
        },

        prewarmNextUtterance(index) {
            if (!this.continuousReadingActive) return;
            if (this.chunkedParagraphState.has(index)) return;
            for (const queuedChunkIndex of this.chunkedParagraphState.keys()) {
                if (queuedChunkIndex > index) return;
            }

            const effectiveLookahead = this.getEffectiveQueueLookahead();
            let nextIndex = index + effectiveLookahead + 1;
            if (nextIndex < 0 || nextIndex >= this.paragraphsList.length) {
                if (this.paragraphsDirty) {
                    this.refreshParagraphsIfNeeded(true);
                }
                if (nextIndex < 0 || nextIndex >= this.paragraphsList.length) return;
            }
            this.enqueueParagraph(nextIndex);
        },

        readFromParagraph(index, options = {}) {
            if (!this.continuousReadingActive) {
                this.revertParagraph();
                return;
            }
            this.requestPlaybackLock(`readFromParagraph:${index}`, (granted) => {
                if (!granted) {
                    this.continuousReadingActive = false;
                    this.ttsActive = false;
                    return;
                }

                this.logPlaybackGuardEvent('read-from-paragraph', {
                    playbackSessionId: this.playbackSessionId,
                    index,
                    hasStartChar: Number.isFinite(Number(options && options.startCharIndex))
                });

                if (index < 0 || index >= this.paragraphsList.length) {
                    this.stopTTS(false);
                    return;
                }

                if (this.isServerVoiceSelected()) {
                    this.advancePlaybackSession('server-voice-read-from-paragraph');
                    this.startServerPlaybackFromParagraph(index, options);
                    return;
                }

                this.queueFromIndex(index, options);
            });
        },

        stopTTS(notify = true) {
            this.advancePlaybackSession('stopTTS');
            this.ttsActive = false;
            this.isPaused = false;
            this.isNavigating = false;
            this.continuousReadingActive = false;
            this.pendingNavIndex = -1;
            this.navKeyHeld = false;
            clearTimeout(this.navigationTimeoutId);
            clearTimeout(this.selectionSeekDebounceId);
            clearTimeout(this.hiddenPauseTimeoutId);
            this.selectionSeekDebounceId = null;
            this.hiddenPauseTimeoutId = null;
            clearTimeout(this.chunkContinuationTimeoutId);
            this.chunkContinuationTimeoutId = null;
            this.stopServerAudioPlayback();
            this.serverPlaybackState = null;
            this.clearServerSentenceCache();
            if (this.speechSynthesis.speaking || this.speechSynthesis.pending) {
                this.speechSynthesis.cancel();
            }
            this.queuedParagraphs.clear();
            this.waitingForMoreContent = false;
            this.waitForMoreNextIndex = -1;
            clearTimeout(this.waitForMoreTimeoutId);
            this.waitForMoreTimeoutId = null;
            this.clearPrewrappedParagraphs();
            this.flushPendingReverts();
            this.revertParagraph();
            this.currentParagraphIndex = -1;
            this.currentUtteranceStartOffset = 0;
            this.queuedStartOffsets.clear();
            this.chunkedParagraphState.clear();
            this.interruptedRetryAttempts.clear();
            this.wordHighlightActiveForCurrent = false;
            this.lastUtteranceEndTime = 0;
            this.lastGapMs = null;
            this.lastWrapMs = null;
            this.hiddenSince = 0;
            this.pausedForHiddenTab = false;

            // Stop the pointer arrow loop and hide the arrow
            if (this.pointerLoopId) {
                cancelAnimationFrame(this.pointerLoopId);
                this.pointerLoopId = null;
            }
            this.hidePointerArrow();
            this.stopAutoScroll();
            this.updateProgressPanel(true);
            this.releasePlaybackLock('stop');

            if (notify) this.showNotification('All TTS stopped');
            return true;
        },

        shouldHighlightWordsForElement(element) {
            if (!this.CONFIG.WORD_HIGHLIGHT_ENABLED) return false;
            if (!element) return false;
            const rect = element.getBoundingClientRect();
            const viewportHeight = window.innerHeight || document.documentElement.clientHeight;
            return rect.bottom > 0 && rect.top < viewportHeight;
        },

        // ... (pauseResumeTTS, navigate, startReadingOnClick, setupEventListeners are unchanged) ...
        pauseResumeTTS() {
            if (this.serverAudioElement) {
                if (this.isPaused) {
                    this.serverAudioElement.play().catch(() => {});
                    this.isPaused = false;
                    this.ttsActive = true;
                    this.showNotification('Resumed');
                } else {
                    this.serverAudioElement.pause();
                    this.isPaused = true;
                    this.ttsActive = false;
                    this.showNotification('Paused');
                }
                return;
            }
            if (!this.speechSynthesis.speaking && !this.isPaused) return;
            if (this.isPaused) {
                this.speechSynthesis.resume();
                this.isPaused = false;
                this.showNotification('Resumed');
            } else {
                this.speechSynthesis.pause();
                this.isPaused = true;
                this.showNotification('Paused');
            }
        },

        isPlaybackSessionActive() {
            const synth = this.speechSynthesis;
            const synthBusy = Boolean(synth && (synth.speaking || synth.pending || synth.paused));
            const serverBusy = Boolean(this.serverAudioElement && !this.serverAudioElement.paused);
            return synthBusy ||
                serverBusy ||
                this.ttsActive ||
                this.continuousReadingActive ||
                this.waitingForMoreContent ||
                this.isPaused ||
                this.queuedParagraphs.size > 0;
        },

        clearStalePlaybackFlagsIfIdle() {
            const synth = this.speechSynthesis;
            const synthBusy = Boolean(synth && (synth.speaking || synth.pending || synth.paused));
            const serverBusy = Boolean(this.serverAudioElement && !this.serverAudioElement.paused);
            if (synthBusy || serverBusy || this.continuousReadingActive || this.waitingForMoreContent || this.queuedParagraphs.size > 0) {
                return false;
            }
            const hadStaleFlags = this.ttsActive || this.isPaused;
            if (hadStaleFlags) {
                this.ttsActive = false;
                this.isPaused = false;
            }
            return hadStaleFlags;
        },

        shouldHandleNavigationHotkeys() {
            return this.isPlaybackSessionActive();
        },

        getNavigationJumpStep(multiplier = 1) {
            const parsed = Number(this.CONFIG.NAV_CTRL_JUMP_SEGMENTS);
            const base = Number.isFinite(parsed) ? Math.max(1, Math.round(parsed)) : 5;
            const scaled = Math.max(1, Math.round(base * Number(multiplier || 1)));
            return scaled;
        },

        getSpeedStep() {
            const parsed = Number(this.CONFIG.SPEED_STEP);
            return Number.isFinite(parsed) ? Math.max(0.1, parsed) : 0.2;
        },

        adjustSpeechRateByStep(direction) {
            const delta = this.getSpeedStep() * (direction < 0 ? -1 : 1);
            const nextRate = Math.min(5, Math.max(0.5, this.CONFIG.SPEECH_RATE + delta));
            this.setSpeechRate(nextRate);
        },

        resolveCurrentNavigationIndex() {
            let currentIndex = this.currentParagraphIndex;
            if (currentIndex < 0 || currentIndex >= this.paragraphsList.length || (this.lastSpokenElement && this.paragraphsList[currentIndex].element !== this.lastSpokenElement)) {
                currentIndex = this.lastSpokenElement
                    ? this.paragraphsList.findIndex(p => p.element === this.lastSpokenElement)
                    : -1;
            }

            if (currentIndex === -1) {
                const threshold = window.innerHeight * 0.2;
                currentIndex = this.paragraphsList.findIndex(p => p.element.getBoundingClientRect().bottom > threshold);
                currentIndex = (currentIndex === -1) ? 0 : currentIndex - 1;
            }
            return currentIndex;
        },

        focusNavigationIndex(index, options = {}) {
            const previewOnly = options.previewOnly === true;
            const outOfRangeMessage = options.outOfRangeMessage || null;
            if (index < 0 || index >= this.paragraphsList.length) {
                if (outOfRangeMessage) {
                    this.showNotification(outOfRangeMessage);
                }
                return false;
            }

            const targetElement = this.paragraphsList[index].element;
            this.clearHighlights(true);
            targetElement.classList.add('tts-navigation-focus');
            this.gentleScrollToElement(targetElement);
            this.addNavigationTrailPoint(targetElement);
            this.lastSpokenElement = targetElement;
            this.pendingNavIndex = index;
            clearTimeout(this.navigationTimeoutId);

            if (!previewOnly) {
                this.navigationTimeoutId = setTimeout(() => {
                    if (this.pendingNavIndex === -1) return;
                    this.continuousReadingActive = true;
                    this.readFromParagraph(this.pendingNavIndex);
                }, this.CONFIG.NAV_FOCUS_HOLD_MS);
            }
            return true;
        },

        navigate(direction, options = {}) {
            const previewOnly = options.previewOnly === true;
            this.isNavigating = true;
            if (this.navigationStateTimeoutId) {
                clearTimeout(this.navigationStateTimeoutId);
            }
            this.navigationStateTimeoutId = setTimeout(() => {
                this.isNavigating = false;
                this.navigationStateTimeoutId = null;
            }, 120);

            this.stopTTS(false);

            this.refreshParagraphsIfNeeded(false);
            if (this.paragraphsList.length === 0) return this.showNotification("No readable text found.");

            const currentFocus = document.querySelector('.tts-navigation-focus');
            if(currentFocus) {
                currentFocus.classList.remove('tts-navigation-focus');
                currentFocus.classList.add('tts-focus-fade-out');
                setTimeout(() => currentFocus.classList.remove('tts-focus-fade-out'), this.CONFIG.NAV_FOCUS_FADE_MS);
            }

            const currentIndex = this.resolveCurrentNavigationIndex();
            const newIndex = currentIndex + direction;
            this.focusNavigationIndex(newIndex, {
                previewOnly,
                outOfRangeMessage: direction > 0 ? 'End of page.' : 'Start of page.'
            });
        },

        jumpToBoundary(boundary, options = {}) {
            this.isNavigating = true;
            if (this.navigationStateTimeoutId) {
                clearTimeout(this.navigationStateTimeoutId);
            }
            this.navigationStateTimeoutId = setTimeout(() => {
                this.isNavigating = false;
                this.navigationStateTimeoutId = null;
            }, 120);

            this.stopTTS(false);
            this.refreshParagraphsIfNeeded(false);
            if (this.paragraphsList.length === 0) {
                this.showNotification('No readable text found.');
                return;
            }

            const currentFocus = document.querySelector('.tts-navigation-focus');
            if (currentFocus) {
                currentFocus.classList.remove('tts-navigation-focus');
                currentFocus.classList.add('tts-focus-fade-out');
                setTimeout(() => currentFocus.classList.remove('tts-focus-fade-out'), this.CONFIG.NAV_FOCUS_FADE_MS);
            }

            const previewOnly = options.previewOnly !== false;
            const targetIndex = boundary === 'start' ? 0 : this.paragraphsList.length - 1;
            this.focusNavigationIndex(targetIndex, { previewOnly });
        },

        replayCurrentParagraph() {
            const index = this.currentParagraphIndex;
            if (!Number.isInteger(index) || index < 0) return;
            this.stopTTS(false);
            this.continuousReadingActive = true;
            this.readFromParagraph(index);
        },

        startReadingFromPendingNav() {
            if (this.pendingNavIndex === -1) return;
            clearTimeout(this.navigationTimeoutId);
            this.navigationTimeoutId = setTimeout(() => {
                if (this.pendingNavIndex === -1) return;
                this.continuousReadingActive = true;
                this.readFromParagraph(this.pendingNavIndex);
            }, this.CONFIG.NAV_KEYUP_READ_DELAY_MS);
        },

        startReadingOnClick(event) {
            if (event.target.closest('#thread-bottom-container')) return;

            this.stopTTS(false);
            this.refreshParagraphsIfNeeded(true);
            let startParaIndex = -1;

            const containingParagraph = this.paragraphsList.find(p => p.element.contains(event.target));
            if (containingParagraph) {
                startParaIndex = this.paragraphsList.indexOf(containingParagraph);
            } else {
                const clickY = event.clientY;
                for(let i = 0; i < this.paragraphsList.length; i++) {
                    const rect = this.paragraphsList[i].element.getBoundingClientRect();
                    if (rect.top > clickY) {
                        startParaIndex = i;
                        break;
                    }
                }
            }

            if (startParaIndex !== -1) {
                this.continuousReadingActive = true;
                this.readFromParagraph(startParaIndex);
            } else {
                this.showNotification('No readable text found at or below your click.');
            }
        },

        startReadingFromTop() {
            this.stopTTS(false);
            this.refreshParagraphsIfNeeded(true);
            if (this.paragraphsList.length === 0) {
                this.showNotification('No readable text found.');
                return;
            }
            this.continuousReadingActive = true;
            this.readFromParagraph(0);
        },

        startReadingFromSelection() {
            const selection = window.getSelection();
            const selectedText = selection ? selection.toString() : '';
            const cleaned = this.cleanTextForTTS(selectedText).trim();
            if (!cleaned) {
                this.showNotification('No text selected.');
                return;
            }
            this.stopTTS(false);
            this.continuousReadingActive = false;
            this.triggerTTS(cleaned);
        },

        startReadingFromViewport() {
            this.stopTTS(false);
            this.refreshParagraphsIfNeeded(true);
            if (this.paragraphsList.length === 0) {
                this.showNotification('No readable text found.');
                return;
            }

            const threshold = window.innerHeight * 0.2;
            let startIndex = this.paragraphsList.findIndex(p => p.element.getBoundingClientRect().bottom > threshold);
            if (startIndex === -1) startIndex = 0;

            this.continuousReadingActive = true;
            this.readFromParagraph(startIndex);
        },

        navigateImmediate(direction) {
            this.navigate(direction, { previewOnly: true });
            if (this.pendingNavIndex === -1) return;
            this.continuousReadingActive = true;
            this.readFromParagraph(this.pendingNavIndex);
        },

        setupEventListeners() {
            document.addEventListener('keydown', (e) => {
                this.markUserInteraction();
                this.capturePromptForNativeEnterSend(e);
                this.handleEnterToSend(e);
                if (this.handlePromptHistoryHotkeys(e)) return;

                const activeEl = document.activeElement;
                if (activeEl && (activeEl.tagName === 'INPUT' || activeEl.tagName === 'TEXTAREA' || activeEl.isContentEditable)) return;
                const key = e.key;
                const keyLower = String(key || '').toLowerCase();
                const shiftOnly = e.shiftKey && !e.ctrlKey && !e.altKey && !e.metaKey;
                const ctrlShift = e.ctrlKey && e.shiftKey;
                const ctrlOrMeta = e.ctrlKey || e.metaKey;
                const KEY = this.CONFIG.HOTKEYS;
                const isNavKey = key === KEY.NAV_NEXT || key === KEY.NAV_PREV;
                const sessionHotkeysActive = this.shouldHandleNavigationHotkeys();
                const canUseIdleNav = this.CONFIG.IDLE_ARROW_NAVIGATION;

                if (isNavKey && !sessionHotkeysActive && !canUseIdleNav) {
                    this.navKeyHeld = false;
                    return;
                }

                if ((key === 'Home' || key === 'End') && sessionHotkeysActive) {
                    e.preventDefault();
                    this.navKeyHeld = false;
                    const previewOnly = !ctrlOrMeta;
                    this.jumpToBoundary(key === 'Home' ? 'start' : 'end', { previewOnly });
                    return;
                }

                if ((key === ' ' || key === 'Spacebar') && sessionHotkeysActive) {
                    e.preventDefault();
                    this.pauseResumeTTS();
                    return;
                }

                if ((key === '[' || key === ']') && sessionHotkeysActive && !ctrlOrMeta && !e.altKey) {
                    e.preventDefault();
                    this.adjustSpeechRateByStep(key === '[' ? -1 : 1);
                    return;
                }

                if (sessionHotkeysActive && !ctrlOrMeta && !e.altKey) {
                    if (keyLower === 'r') {
                        e.preventDefault();
                        this.replayCurrentParagraph();
                        return;
                    }
                    if (keyLower === 'l') {
                        e.preventDefault();
                        this.setLoopEnabled(!this.CONFIG.LOOP_ON_END);
                        persistProfileSetting(this.settingsProfile, 'loopOnEnd', this.CONFIG.LOOP_ON_END);
                        return;
                    }
                    if (keyLower === 'a') {
                        e.preventDefault();
                        this.setAutoScrollEnabled(!this.CONFIG.AUTO_SCROLL_ENABLED);
                        persistProfileSetting(this.settingsProfile, 'autoScrollEnabled', this.CONFIG.AUTO_SCROLL_ENABLED);
                        return;
                    }
                }

                switch (key) {
                    case KEY.NAV_NEXT:
                        e.preventDefault();
                        this.navKeyHeld = true;
                        this.navigate(ctrlOrMeta ? this.getNavigationJumpStep() : 1, { previewOnly: true });
                        break;
                    case KEY.NAV_PREV:
                        e.preventDefault();
                        this.navKeyHeld = true;
                        this.navigate(ctrlOrMeta ? -this.getNavigationJumpStep() : -1, { previewOnly: true });
                        break;
                    case KEY.STOP: e.preventDefault(); this.stopTTS(); break;
                }

                if (shiftOnly && key.toUpperCase() === KEY.ACTIVATE) {
                    e.preventDefault();
                    this.clearStalePlaybackFlagsIfIdle();
                    if (this.isPlaybackSessionActive()) { this.stopTTS(); return; }
                    document.body.style.cursor = 'crosshair';
                    this.showNotification('Click where you want to start reading');

                    const clickHandler = (ev) => {
                        ev.preventDefault();
                        ev.stopPropagation();
                        document.body.style.cursor = 'default';
                        this.startReadingOnClick(ev);
                    };
                    document.addEventListener('click', clickHandler, { once: true, capture: true });
                } else if (ctrlShift && key.toUpperCase() === KEY.PAUSE_RESUME) {
                    e.preventDefault();
                    this.pauseResumeTTS();
                }
            });
            document.addEventListener('keyup', (e) => {
                const activeEl = document.activeElement;
                if (activeEl && (activeEl.tagName === 'INPUT' || activeEl.tagName === 'TEXTAREA' || activeEl.isContentEditable)) return;

                const key = e.key;
                const KEY = this.CONFIG.HOTKEYS;
                if (key === KEY.NAV_NEXT || key === KEY.NAV_PREV) {
