* {
    box-sizing: border-box;
}

:root {
    color-scheme: light dark;
    --opt-bg: #f5f6f8;
    --opt-text: #1f2937;
    --opt-muted: #667085;
    --opt-primary: #1a73e8;
    --opt-primary-hover: #1557b0;
    --opt-card-bg: #ffffff;
    --opt-card-border: #dde3ec;
    --opt-card-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
    --opt-input-bg: #ffffff;
    --opt-input-border: #d4dbe5;
    --opt-pill-bg: #e8f0fe;
    --opt-pill-border: #d2e3fc;
    --opt-pill-text: #1a73e8;
    --opt-secondary-bg: #eef2f7;
    --opt-secondary-hover: #e4e9f1;
    --opt-secondary-text: #4b5563;
    --opt-secondary-border: #d4dbe5;
}

@media (prefers-color-scheme: dark) {
    :root {
        --opt-bg: #111418;
        --opt-text: #e5e7eb;
        --opt-muted: #9ca3af;
        --opt-primary: #4f9bff;
        --opt-primary-hover: #67a7ff;
        --opt-card-bg: #161b22;
        --opt-card-border: #2a313d;
        --opt-card-shadow: 0 1px 2px rgba(0, 0, 0, 0.35);
        --opt-input-bg: #1f2630;
        --opt-input-border: #364152;
        --opt-pill-bg: #1b2c44;
        --opt-pill-border: #2b4f78;
        --opt-pill-text: #9ec5ff;
        --opt-secondary-bg: #1f2630;
        --opt-secondary-hover: #26303d;
        --opt-secondary-text: #d1d5db;
        --opt-secondary-border: #364152;
    }
}

body {
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif;
    background: var(--opt-bg);
    color: var(--opt-text);
}

.page {
    max-width: 920px;
    margin: 24px auto 40px;
    padding: 0 20px;
}

.page-header {
    margin-bottom: 20px;
}

.page-header h1 {
    margin: 0 0 6px;
    font-size: 26px;
    color: var(--opt-primary);
}

.page-header p {
    margin: 0;
    color: var(--opt-muted);
    font-size: 14px;
}

.card {
    background: var(--opt-card-bg);
    border: 1px solid var(--opt-card-border);
    border-radius: 12px;
    padding: 16px 20px;
    margin-bottom: 16px;
    box-shadow: var(--opt-card-shadow);
}

.card h2 {
    margin: 0 0 12px;
    font-size: 16px;
    color: var(--opt-text);
}

.field {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    margin: 10px 0;
    font-size: 14px;
}

.field label {
    color: var(--opt-text);
}

.field.toggle input {
    transform: scale(1.1);
}

.field.toggle label {
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.range-row {
    display: flex;
    align-items: center;
    gap: 12px;
    flex: 1;
}

.range-row input[type="range"] {
    flex: 1;
}

.value-pill {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 48px;
    padding: 4px 8px;
    border-radius: 14px;
    background: var(--opt-pill-bg);
    color: var(--opt-pill-text);
    border: 1px solid var(--opt-pill-border);
    font-size: 12px;
}

.grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
    gap: 12px;
}

.field input[type="number"],
.field select,
.field textarea {
    width: 100%;
    padding: 6px 8px;
    border-radius: 6px;
    border: 1px solid var(--opt-input-border);
    font-size: 13px;
    background: var(--opt-input-bg);
    color: var(--opt-text);
}

.field textarea {
    resize: vertical;
    line-height: 1.35;
    min-height: 84px;
}

.field.field-block {
    flex-direction: column;
    align-items: stretch;
    gap: 8px;
}

.note {
    margin: 8px 0 0;
    font-size: 12px;
    color: var(--opt-muted);
}

.note-list {
    margin: 0;
    padding-left: 18px;
    color: var(--opt-muted);
    font-size: 13px;
    line-height: 1.5;
}

.note-list li + li {
    margin-top: 4px;
}

.actions {
    display: flex;
    justify-content: flex-end;
    gap: 12px;
}

.button {
    border: 1px solid transparent;
    border-radius: 6px;
    padding: 8px 14px;
    font-size: 14px;
    cursor: pointer;
    transition: background 0.2s ease;
}

.button.primary {
    background: var(--opt-primary);
    color: #fff;
}

.button.primary:hover {
    background: var(--opt-primary-hover);
}

.button.secondary {
    background: var(--opt-secondary-bg);
    color: var(--opt-secondary-text);
    border-color: var(--opt-secondary-border);
}

.button.secondary:hover {
    background: var(--opt-secondary-hover);
}

@media (max-width: 600px) {
    .field {
        flex-direction: column;
        align-items: stretch;
    }

    .actions {
        flex-direction: column;
        align-items: stretch;
    }
}

